import type { FieldDesc, FieldLayout, StructDefLike, UnionDefLike } from './index.js';

export interface RustCodegenOptions {
  /** Additional `#[derive(...)]` traits (default: `['Copy', 'Clone', 'Debug', 'PartialEq']`). */
  derive?: readonly string[];
  /** Emit compile-time size/align/offset_of assertions (default: `true`). */
  assertions?: boolean;
  /** Visibility modifier for structs and fields (default: `'pub'`). */
  vis?: 'pub' | 'pub(crate)' | '';
  /** Emit `extern crate alloc;`, `CapnBuilder`, and `capn_alloc`/`capn_reset` WASM arena exports (default: `false`). */
  wasm?: boolean;
}

export interface GoCodegenOptions {
  /** Go package name (default: `'capnschema'`, or `'main'` when `wasm: true`). */
  pkg?: string;
  /** Emit compile-time size/align/offsetof assertions (default: `true`). */
  assertions?: boolean;
  /** Emit `//go:wasmexport capn_alloc` & `capn_reset` arena helpers for Go (`GOOS=wasip1 GOARCH=wasm`) and TinyGo (`-target=wasi`) WebAssembly (default: `false`). */
  wasm?: boolean;
}

export type SchemaDef = StructDefLike<any> | UnionDefLike<any>;
export type SchemaCollection = SchemaDef | readonly SchemaDef[] | Record<string, unknown>;

function collectDefs(input: SchemaCollection): SchemaDef[] {
  const seen = new Set<string>(),
    out: SchemaDef[] = [],
    visit = (d: unknown, name?: string): void => {
      if (!d || typeof d !== 'object') return;
      const f = d as FieldDesc & { element?: FieldDesc };
      const nm = name || ('name' in f && f.name) || (f.kind === 'union' ? 'AnonUnion' : 'AnonStruct');
      if (f.kind === 'struct') {
        if (!seen.has(nm)) {
          seen.add(nm);
          for (const fl of f.fieldList) visit(fl.desc);
          out.push({ ...f, name: nm, rustType: nm });
        }
      } else if (f.kind === 'union') {
        if (!seen.has(nm)) {
          seen.add(nm);
          for (const vr of f.variantList) if (vr.desc) visit(vr.desc);
          out.push({ ...f, name: nm, rustType: nm });
        }
      } else if (f.element) visit(f.element);
    };
  if (input && typeof input === 'object' && ('kind' in input) && (input.kind === 'struct' || input.kind === 'union')) {
    const def = input as SchemaDef;
    visit(def, def.name || 'Root');
  } else {
    for (const [k, v] of Object.entries(input)) {
      const vn = v && typeof v === 'object' && 'name' in v && typeof v.name === 'string' ? v.name : '';
      visit(v, vn || (Array.isArray(input) ? `Struct${k}` : k));
    }
  }
  return out;
}

const hasFloat = (d: FieldDesc, s = new Set<FieldDesc>()): boolean => {
  if (s.has(d)) return false;
  s.add(d);
  if (d.kind === 'primitive') return 'float' in d && d.float;
  if (d.kind === 'array' || d.kind === 'slice' || d.kind === 'ref') return hasFloat(d.element as FieldDesc, s);
  if (d.kind === 'union') return d.variantList.some((vr) => vr.desc !== null && hasFloat(vr.desc, s));
  if (d.kind === 'struct') return d.fieldList.some((f) => hasFloat(f.desc, s));
  return false;
};

const HDR = '// Auto-generated by capnstruct. DO NOT EDIT.\n';
const ALW = '#[allow(dead_code, non_camel_case_types, non_snake_case)]\n';

const fmtBody = (def: StructDefLike, fmtF: (f: FieldLayout) => string, fmtP: (p: string, n: number) => string): string => {
  let cur = 0,
    pad = 0;
  const out: string[] = [];
  for (const f of def.fieldList) {
    if (f.offset > cur) out.push(fmtP(`_pad${pad++}`, f.offset - cur));
    out.push(fmtF(f));
    cur = f.offset + f.size;
  }
  if (def.size > cur) out.push(fmtP(`_pad${pad}`, def.size - cur));
  return out.join('\n');
};

export function toRustReprC(schemas: SchemaCollection, opts: RustCodegenOptions = {}): string {
  const defs = collectDefs(schemas),
    drv0 = opts.derive ?? ['Copy', 'Clone', 'Debug', 'PartialEq'],
    drvEq = opts.derive ? drv0 : [...drv0, 'Eq'],
    v = opts.vis === '' ? '' : `${opts.vis ?? 'pub'} `,
    drv = (d: readonly string[]) => (d.length ? `#[derive(${d.join(', ')})]\n` : ''),
    eDrv = drv(drvEq),
    hdr = (t: string, f = 'len', m = '') => `${ALW}#[repr(C)]\n${eDrv}${v}struct ${t} {\n  ${v}off: u32,\n  ${v}${f}: u32,${m}\n}`,
    mk = `\n  ${v}_marker: core::marker::PhantomData<T>,`,
    blocks = [
      `${HDR}${opts.wasm ? 'extern crate alloc;\n' : ''}${ALW}fn _cs<T>(b: &[u8], o: usize, n: usize) -> &[T] {\n  if n == 0 { return &[]; }\n  let s = &b[o..o.checked_add(n.checked_mul(core::mem::size_of::<T>()).unwrap()).unwrap()];\n  unsafe { core::slice::from_raw_parts(s.as_ptr() as *const T, n) }\n}\n${hdr('CapnStr')}\n${ALW}impl CapnStr {\n  ${v}fn as_bytes<'a>(&self, b: &'a [u8]) -> &'a [u8] { _cs(b, self.off as usize, self.len as usize) }\n  ${v}fn as_str<'a>(&self, b: &'a [u8]) -> Result<&'a str, core::str::Utf8Error> { core::str::from_utf8(self.as_bytes(b)) }\n}\n${hdr('CapnSlice<T>', 'len', mk)}\n${ALW}impl<T> CapnSlice<T> {\n  ${v}fn as_slice<'a>(&self, b: &'a [u8]) -> &'a [T] { _cs(b, self.off as usize, self.len as usize) }\n}\n${hdr('CapnRef<T>', 'present', mk)}\n${ALW}impl<T> CapnRef<T> {\n  ${v}fn as_ref<'a>(&self, b: &'a [u8]) -> Option<&'a T> {\n    if self.present == 0 { None } else { _cs(b, self.off as usize, 1).first() }\n  }\n}`,
    ];
  if (opts.wasm) {
    blocks.push(
      `${ALW}#[derive(Default)]\n${v}struct CapnBuilder {\n  ${v}buf: alloc::vec::Vec<u8>,\n  dedup: alloc::collections::BTreeMap<alloc::string::String, CapnStr>,\n}\n${ALW}impl CapnBuilder {\n  ${v}const fn new() -> Self { Self { buf: alloc::vec::Vec::new(), dedup: alloc::collections::BTreeMap::new() } }\n  ${v}fn reset(&mut self) { self.buf.clear(); self.dedup.clear(); }\n  ${v}fn alloc(&mut self, n: usize, a: usize) -> usize { let a = if a == 0 { 1 } else { a }; let o = (self.buf.len() + a - 1) & !(a - 1); self.buf.resize(o + n, 0); o }\n  ${v}fn str(&mut self, s: &str) -> CapnStr { let b = s.as_bytes(); if b.is_empty() { return CapnStr { off: 0, len: 0 }; } let o = self.alloc(b.len(), 1); self.buf[o..o + b.len()].copy_from_slice(b); CapnStr { off: o as u32, len: b.len() as u32 } }\n  ${v}fn str_dedup(&mut self, s: &str) -> CapnStr { if s.is_empty() { return CapnStr { off: 0, len: 0 }; } if let Some(&c) = self.dedup.get(s) { return c; } let c = self.str(s); self.dedup.insert(alloc::string::String::from(s), c); c }\n  ${v}fn bytes(&self) -> &[u8] { &self.buf }\n  ${v}fn build_slice<T: Copy>(&mut self, n: usize, mut f: impl FnMut(usize, &mut Self) -> T) -> CapnSlice<T> { if n == 0 { return CapnSlice { off: 0, len: 0, _marker: core::marker::PhantomData }; } let sz = core::mem::size_of::<T>(); let o = self.alloc(n * sz, core::mem::align_of::<T>()); for i in 0..n { let v = f(i, self); unsafe { core::ptr::write_unaligned(self.buf.as_mut_ptr().add(o + i * sz) as *mut T, v); } } CapnSlice { off: o as u32, len: n as u32, _marker: core::marker::PhantomData } }\n  ${v}fn build<T: Copy>(&mut self, f: impl FnOnce(&mut Self) -> T) -> &[u8] { self.reset(); let mut f = Some(f); self.build_slice(1, |_, b| f.take().unwrap()(b)); let e = (self.buf.len() + 7) & !7; self.buf.resize(e, 0); &self.buf }\n  ${v}fn pack_slice<T: Copy>(&mut self, s: &[T]) -> CapnSlice<T> { self.build_slice(s.len(), |i, _| s[i]) }\n  ${v}fn pack<T: Copy>(&mut self, s: &[T]) -> &[u8] { self.reset(); self.pack_slice(s); let e = (self.buf.len() + 7) & !7; self.buf.resize(e, 0); &self.buf }\n  ${v}fn pack_ref<T: Copy>(&mut self, v: Option<T>) -> CapnRef<T> { match v { None => CapnRef { off: 0, present: 0, _marker: core::marker::PhantomData }, Some(x) => { let s = self.build_slice(1, |_, _| x); CapnRef { off: s.off, present: 1, _marker: core::marker::PhantomData } } } }\n  ${v}fn build_ref<T: Copy>(&mut self, f: impl FnOnce(&mut Self) -> T) -> CapnRef<T> { let mut f = Some(f); let s = self.build_slice(1, |_, b| f.take().unwrap()(b)); CapnRef { off: s.off, present: 1, _marker: core::marker::PhantomData } }\n}\n${ALW}struct _CapnCell(core::cell::UnsafeCell<CapnBuilder>);\nunsafe impl Sync for _CapnCell {}\nstatic _CAPN_B: _CapnCell = _CapnCell(core::cell::UnsafeCell::new(CapnBuilder::new()));\n${ALW}#[unsafe(no_mangle)]\npub extern "C" fn capn_alloc(n: u32) -> *mut u8 { if n == 0 { return core::ptr::null_mut(); } unsafe { let b = &mut *_CAPN_B.0.get(); let o = b.alloc(n as usize, 8); b.buf.as_mut_ptr().add(o) } }\n${ALW}#[unsafe(no_mangle)]\npub extern "C" fn capn_reset() { unsafe { (&mut *_CAPN_B.0.get()).reset(); } }`,
    );
  }
  for (const def of defs) {
    const n = def.name,
      u = (e: string, s: number) => `  assert!(core::mem::${e} == ${s});`,
      dLine = drv(hasFloat(def) ? drv0 : drvEq);
    if (def.kind === 'union') {
      const repr = def.unitOnly ? '#[repr(u8)]' : '#[repr(C, u8)]',
        body = def.variantList
          .map((vr) => `  ${vr.name}${vr.desc === null ? '' : `(${vr.desc.rustType})`} = ${vr.tag},`)
          .join('\n'),
        a =
          opts.assertions ?? true
            ? `\nconst _: () = {\n${u(`size_of::<${n}>()`, def.size)}\n${u(`align_of::<${n}>()`, def.align)}\n};`
            : '';
      blocks.push(`${ALW}${repr}\n${dLine}${v}enum ${n} {\n${body}\n}${a}`);
    } else {
      const body = fmtBody(
          def,
          (f) => `  ${v}${f.name}: ${f.desc.rustType},`,
          (p, s) => `  ${v}${p}: [u8; ${s}],`,
        ),
        a =
          opts.assertions ?? true
            ? `\nconst _: () = {\n${u(`size_of::<${n}>()`, def.size)}\n${u(`align_of::<${n}>()`, def.align)}\n${def.fieldList.map((f) => u(`offset_of!(${n}, ${f.name})`, f.offset)).join('\n')}\n};`
            : '';
      blocks.push(
        `${ALW}#[repr(C)]\n${dLine}${v}struct ${n} {\n${body}\n}\n${ALW}impl ${n} {\n  ${v}fn as_slice(base: &[u8], len: usize) -> &[Self] { _cs(base, 0, len) }\n}${a}`,
      );
    }
  }
  return blocks.join('\n\n') + '\n';
}

export const generateRust = toRustReprC;

const goType = (d: FieldDesc): string => {
  if (d.kind === 'primitive') {
    const t = d.type;
    return t > 'fixed' && t < 'fo'
      ? `[${(d as { length: number }).length}]byte`
      : t === 'bool'
        ? 'uint8'
        : t === 'f16'
          ? 'uint16'
          : (t[0] === 'f' ? 'float' : t[0] === 'u' ? 'uint' : 'int') + t.slice(1);
  }
  return d.kind === 'str'
    ? 'CapnStr'
    : d.kind === 'struct' || d.kind === 'union'
      ? d.name || (d.kind === 'union' ? 'AnonUnion' : 'AnonStruct')
      : d.kind === 'array'
        ? `[${d.length}]${goType(d.element)}`
        : `Capn${d.kind === 'ref' ? 'Ref' : 'Slice'}[${goType(d.element as FieldDesc)}]`;
};

const goField = (s: string) => s[0].toUpperCase() + s.slice(1);

export function toGoStruct(schemas: SchemaCollection, opts: GoCodegenOptions = {}): string {
  const defs = collectDefs(schemas),
    wasm = opts.wasm ?? false,
    blocks = [
      `${HDR}package ${opts.pkg || (wasm ? 'main' : 'capnschema')}\n\nimport "unsafe"`,
      ...(wasm
        ? [
            `var _capnB CapnBuilder\n//go:wasmexport capn_alloc\nfunc CapnAlloc(n uint32) uintptr {\n\tif n == 0 { return 0 }\n\treturn uintptr(unsafe.Pointer(&_capnB.Buf[_capnB.alloc(int(n), 8)]))\n}\n//go:wasmexport capn_reset\nfunc CapnReset() { _capnB.Reset() }`,
          ]
        : []),
      `func CapnBytes(ptr uintptr, byteLen uint32) []byte {\n\tif ptr == 0 || byteLen == 0 { return nil }\n\treturn unsafe.Slice((*byte)(unsafe.Pointer(ptr)), byteLen)\n}\nfunc CapnView[T any](b []byte) *T { return &CapnSliceView[T](b, 1)[0] }\nfunc CapnSliceView[T any](b []byte, n uint32) []T {\n\tif n == 0 { return nil }\n\tvar z T\n\tif uint64(n)*uint64(unsafe.Sizeof(z)) > uint64(len(b)) { panic("oob") }\n\treturn unsafe.Slice((*T)(unsafe.Pointer(unsafe.SliceData(b))), n)\n}\ntype CapnStr struct{ Off, Len uint32 }\nfunc (s CapnStr) Bytes(b []byte) []byte { return CapnSliceView[byte](b[s.Off:], s.Len) }\nfunc (s CapnStr) String(b []byte) string { return unsafe.String(unsafe.SliceData(s.Bytes(b)), s.Len) }\ntype CapnSlice[T any] struct{ Off, Len uint32 }\nfunc (s CapnSlice[T]) Slice(b []byte) []T { return CapnSliceView[T](b[s.Off:], s.Len) }\ntype CapnRef[T any] struct{ Off, Present uint32 }\nfunc (r CapnRef[T]) Ptr(b []byte) *T {\n\tif r.Present == 0 { return nil }\n\treturn CapnView[T](b[r.Off:])\n}\ntype CapnBuilder struct {\n\tBuf []byte\n\tdedup map[string]CapnStr\n}\nfunc (b *CapnBuilder) Reset(buf ...[]byte) {\n\tif len(buf) > 0 { b.Buf = buf[0][:0] } else { b.Buf = b.Buf[:0] }\n\tclear(b.dedup)\n}\nfunc (b *CapnBuilder) alloc(n, a int) int {\n\tp := len(b.Buf)\n\to := (p + a - 1) &^ (a - 1)\n\te := o + n\n\tif e > cap(b.Buf) { b.Buf = append(b.Buf, make([]byte, e-p)...) }\n\tb.Buf = b.Buf[:e]\n\tclear(b.Buf[p:e])\n\treturn o\n}\nfunc (b *CapnBuilder) Str(s string) CapnStr {\n\treturn CapnStr(CapnPackSlice(b, unsafe.Slice(unsafe.StringData(s), len(s))))\n}\nfunc (b *CapnBuilder) StrDedup(s string) CapnStr {\n\tif c, ok := b.dedup[s]; ok || s == "" { return c }\n\tif b.dedup == nil { b.dedup = map[string]CapnStr{} }\n\tb.dedup[s] = b.Str(s)\n\treturn b.dedup[s]\n}\nfunc (b *CapnBuilder) Bytes() []byte { return b.Buf }\nfunc CapnBuildSlice[T any](b *CapnBuilder, n int, fn func(int, *CapnBuilder) T) CapnSlice[T] {\n\tif n <= 0 { return CapnSlice[T]{} }\n\tvar z T\n\to := b.alloc(n*int(unsafe.Sizeof(z)), int(unsafe.Alignof(z)))\n\tfor i := 0; i < n; i++ {\n\t\tv := fn(i, b)\n\t\tCapnSliceView[T](b.Buf[o:], uint32(n))[i] = v\n\t}\n\treturn CapnSlice[T]{uint32(o), uint32(n)}\n}\nfunc CapnBuild[T any](b *CapnBuilder, fn func(*CapnBuilder) T) []byte {\n\tb.Reset()\n\tCapnBuildSlice(b, 1, func(_ int, b *CapnBuilder) T { return fn(b) })\n\treturn b.Buf\n}\nfunc CapnPackSlice[T any](b *CapnBuilder, s []T) CapnSlice[T] {\n\treturn CapnBuildSlice(b, len(s), func(i int, _ *CapnBuilder) T { return s[i] })\n}\nfunc CapnPack[T any](b *CapnBuilder, s []T) []byte {\n\tb.Reset()\n\tCapnPackSlice(b, s)\n\treturn b.Buf\n}\nfunc CapnPackRef[T any](b *CapnBuilder, v *T) CapnRef[T] {\n\tif v == nil { return CapnRef[T]{} }\n\treturn CapnRef[T]{CapnPackSlice(b, unsafe.Slice(v, 1)).Off, 1}\n}`,
    ];
  for (const def of defs) {
    const n = def.name,
      u = (e: string, s: number) => `\t_ = [1]int{}[unsafe.${e}-${s}]`;
    if (def.kind === 'union') {
      if (def.unitOnly) {
        const cs = def.variantList.map((vr) => `\t${n}${goField(vr.name)} ${n} = ${vr.tag}`).join('\n'),
          a =
            opts.assertions ?? true
              ? `\nvar (\n${u(`Sizeof(${n}(0))`, def.size)}\n${u(`Alignof(${n}(0))`, def.align)}\n)`
              : '';
        blocks.push(`type ${n} uint8\nconst (\n${cs}\n)${a}`);
      } else {
        const a = def.align,
          dataEl = a === 8 ? 'uint64' : a === 4 ? 'uint32' : a === 2 ? 'uint16' : 'byte',
          cs = def.variantList.map((vr) => `\t${n}${goField(vr.name)} uint8 = ${vr.tag}`).join('\n'),
          fields = [
            '\tTag uint8',
            ...(a > 1 ? [`\t_pad0 [${a - 1}]byte`] : []),
            ...(def.size > a ? [`\tData [${(def.size - a) / a}]${dataEl}`] : []),
          ].join('\n'),
          helpers = def.variantList
            .map((vr) => {
              const vn = goField(vr.name);
              if (vr.desc === null) return `func ${n}Make${vn}() ${n} { return ${n}{Tag: ${vr.tag}} }`;
              const gt = goType(vr.desc);
              return `func (u *${n}) As${vn}() *${gt} { return (*${gt})(unsafe.Add(unsafe.Pointer(u), ${vr.payloadOffset})) }\nfunc ${n}Make${vn}(v ${gt}) ${n} { var u ${n}; u.Tag = ${vr.tag}; *u.As${vn}() = v; return u }`;
            })
            .join('\n'),
          asrt =
            opts.assertions ?? true
              ? `\nvar (\n${u(`Sizeof(${n}{})`, def.size)}\n${u(`Alignof(${n}{})`, def.align)}\n)`
              : '';
        blocks.push(`const (\n${cs}\n)\ntype ${n} struct {\n${fields}\n}\n${helpers}${asrt}`);
      }
    } else {
      const body = fmtBody(
          def,
          (f) => `\t${goField(f.name)} ${goType(f.desc)}`,
          (p, s) => `\t${p} [${s}]byte`,
        ),
        a =
          opts.assertions ?? true
            ? `\nvar (\n${u(`Sizeof(${n}{})`, def.size)}\n${u(`Alignof(${n}{})`, def.align)}\n${def.fieldList.map((f) => u(`Offsetof(${n}{}.${goField(f.name)})`, f.offset)).join('\n')}\n)`
            : '';
      blocks.push(`type ${n} struct {\n${body}\n}${a}`);
    }
  }
  return blocks.join('\n\n') + '\n';
}

export const generateGo = toGoStruct;
